// One line per case: the function's result as JSON, or "raises <Error>".
import { createInterface } from "node:readline";

const [mod, name] = process.argv.slice(2);
const fn = (await import(`./${mod}.mjs`))[name];
for await (const line of createInterface({ input: process.stdin })) {
  const t = line.trim();
  if (!t) continue;
  try {
    const args = JSON.parse(t);
    const out = await (Array.isArray(args) ? fn(...args) : fn(args));
    console.log(out === undefined ? "undefined" : JSON.stringify(out));
  } catch (e) {
    console.log("raises " + (e?.constructor?.name ?? "Error"));
  }
}
